INSERT INTO posture (id, nom, ordre, libelle_fiche, description, origine, source_ref, remarque) VALUES ('guide/postures#posture:defensif', 'Défensif', 2, 'DEFENSIF', 'En opposition avec la posture offensive, la posture défensive est faite pour quelqu''un qui souhaite couvrir ses alliés ou bien se protéger de multiples assauts.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures ; Fiche auto V15.2.2 › Personnage › BR16', NULL);
INSERT INTO posture (id, nom, ordre, libelle_fiche, description, origine, source_ref, remarque) VALUES ('guide/postures#posture:focus', 'Focus', 4, 'FOCUS', 'Cette posture permet de rester concentré et permet une meilleure efficacité avec la magie.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures ; Fiche auto V15.2.2 › Personnage › BA23', NULL);
INSERT INTO posture (id, nom, ordre, libelle_fiche, description, origine, source_ref, remarque) VALUES ('guide/postures#posture:neutre', 'Neutre', 3, 'NEUTRE', 'L''entre-deux de la posture offensive et défensive, la posture neutre permet d''infliger les dégâts normaux en plus de bénéficier de parade ou esquive.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures ; Fiche auto V15.2.2 › Personnage › BI16', NULL);
INSERT INTO posture (id, nom, ordre, libelle_fiche, description, origine, source_ref, remarque) VALUES ('guide/postures#posture:offensif', 'Offensif', 1, 'OFFENSIF', 'C''est la posture d''attaque par excellence, si on veut taper et faire beaucoup de dégâts c''est la posture idéale.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures ; Fiche auto V15.2.2 › Personnage › BA16', NULL);
INSERT INTO posture (id, nom, ordre, libelle_fiche, description, origine, source_ref, remarque) VALUES ('guide/postures#posture:symbiose', 'Symbiose', 6, 'SYMBIOSE', 'Cette posture étrange permet d''être en parfaite fusion avec sa magie, dans cette posture vous êtes presque comme un élémentaire. Il faut savoir que cette posture permet d''être meilleur avec sa magie mais dans le cas où vous êtes bi-magie, vous devez choisir une magie avec qui faire équipe et délaisser l''autre le temps de la posture.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures ; Fiche auto V15.2.2 › Personnage › BR23', NULL);
INSERT INTO posture (id, nom, ordre, libelle_fiche, description, origine, source_ref, remarque) VALUES ('guide/postures#posture:vigilance', 'Vigilance', 5, 'VIGILANCE', 'Cette posture permet d''être bien plus attentif à ce qu''il se passe autour de soi mais aussi dans le combat.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures ; Fiche auto V15.2.2 › Personnage › BI23', NULL);
